package ui

import (
	"github.com/tangoui/tango/ui/a11y"
	"github.com/tangoui/tango/ui/geom"
	"github.com/tangoui/tango/ui/icon"
	"github.com/tangoui/tango/ui/input"
	"github.com/tangoui/tango/ui/layout"
	"github.com/tangoui/tango/ui/paint"
	"github.com/tangoui/tango/ui/text"
	"github.com/tangoui/tango/ui/theme"
)

// ---------------------------------------------------------------------------
// TimeSelect (Element el-time-select)

// TimeSelectW picks a "HH:MM" time from a fixed list generated by
// Start/End/Step.
type TimeSelectW struct {
	c           *Context
	n           *node
	val         *string
	st          *moreTimeSelState
	start, end  string
	step        string
	minT, maxT  string
	placeholder string
	clearable   bool
	disabled    bool
	status      string
	variant     string
	size        ControlSize
	changed     bool
	ia          Interaction
	z           *lazy
	items       []Option
	optIDs      []ID // option nodes of the open list (ActiveDescendant)
}

type moreTimeSelState struct {
	open   bool
	active int
	scroll bool // on open: scroll the value near the top
	follow bool // keyboard move: keep the highlight visible
	panel  ID
	list   ID
	ptr    geom.Point // pointer at the last build: hover only steals the highlight after a move
}

// TimeSelect adds a time select bound to *val ("HH:MM", "" = empty).
// Defaults follow Element: 09:00–18:00 every 00:30.
//
// ConfigProvider.Defaults("TimeSelect", ...) keys: "start", "end",
// "step", "placeholder", "clearable" (Element) / "allowClear", "size",
// "width", "variant".
func TimeSelect(c *Context, val *string) *TimeSelectW {
	w := &TimeSelectW{c: c, val: val, start: "09:00", end: "18:00", step: "00:30", placeholder: c.Locale().SelectTime, clearable: true, status: c.itemStatus, size: c.defaultSize()}
	w.n = c.add("timeselect", "")
	def := p2aDefaults(c, "TimeSelect")
	def.str("start", &w.start)
	def.str("end", &w.end)
	def.str("step", &w.step)
	def.str("placeholder", &w.placeholder)
	def.flag("allowClear", &w.clearable)
	def.flag("clearable", &w.clearable)
	def.size(&w.size)
	def.px("width", &w.n.ln.Width)
	def.str("variant", &w.variant)
	w.n.ln.NoStretch = true
	w.n.ownKeys = true
	w.n.paint = w.paint
	w.st = State[moreTimeSelState](c, w.n.id, nil)
	w.ia = c.interact(w.n, true, input.CursorPointer)
	w.n.setRole(a11y.RoleCombobox).setState(a11y.Expandable | a11y.HasPopup).fill(w)
	w.z = c.lazy(w.n, w.finish)
	return w
}

// A11yLabel sets the accessible name (inside a FormItem the item label is
// used; the placeholder is the last resort).
func (w *TimeSelectW) A11yLabel(s string) *TimeSelectW { w.n.setName(s); return w }

func (w *TimeSelectW) semantics(s *a11y.Node) {
	s.Value, s.Placeholder = *w.val, w.placeholder
	if s.Name == "" {
		s.Name = w.placeholder
	}
	if w.st.open {
		semExpanded(s)
		s.Controls = a11y.NodeID(w.st.list)
		if a := w.st.active; a >= 0 && a < len(w.optIDs) {
			s.ActiveDescendant = a11y.NodeID(w.optIDs[a])
		}
	}
	if w.status == "error" {
		s.States |= a11y.Invalid
	}
}

// Start / End / Step set the generated range ("HH:MM"; End is inclusive).
func (w *TimeSelectW) Start(s string) *TimeSelectW { w.start = s; return w }
func (w *TimeSelectW) End(s string) *TimeSelectW   { w.end = s; return w }
func (w *TimeSelectW) Step(s string) *TimeSelectW  { w.step = s; return w }

// MinTime disables times at or before s; MaxTime disables times at or
// after s (Element semantics).
func (w *TimeSelectW) MinTime(s string) *TimeSelectW { w.minT = s; return w }
func (w *TimeSelectW) MaxTime(s string) *TimeSelectW { w.maxT = s; return w }

func (w *TimeSelectW) Placeholder(s string) *TimeSelectW { w.placeholder = s; return w }

// Clearable shows the clear icon on hover (default on).
func (w *TimeSelectW) Clearable(on bool) *TimeSelectW  { w.clearable = on; return w }
func (w *TimeSelectW) Status(s string) *TimeSelectW    { w.status = s; return w }
func (w *TimeSelectW) Size(s ControlSize) *TimeSelectW { w.size = s; return w }

// Variant sets the frame look: "outlined" (default), "filled",
// "borderless" or "underlined".
func (w *TimeSelectW) Variant(v string) *TimeSelectW { w.variant = v; return w }
func (w *TimeSelectW) Width(px float32) *TimeSelectW { w.n.ln.Width = px; return w }
func (w *TimeSelectW) Layout(o ...layout.Option) *TimeSelectW {
	w.n.ln.Style.Apply(o...)
	return w
}
func (w *TimeSelectW) Disabled(on bool) *TimeSelectW {
	if on {
		w.disabled, w.n.focus, w.n.cursor = true, false, input.CursorNotAllowed
	}
	return w
}

// Open forces the dropdown open (screenshots, tests).
func (w *TimeSelectW) Open() *TimeSelectW {
	if !w.st.open {
		w.st.open, w.st.scroll = true, true
		w.st.active = -1
	}
	return w
}

// IsOpen reports whether the dropdown is shown.
func (w *TimeSelectW) IsOpen() bool { w.z.run(); return w.st.open }

// Changed reports a new value this frame.
func (w *TimeSelectW) Changed() bool { w.z.run(); return w.changed }

// Options returns the generated items (Disabled marks MinTime/MaxTime).
func (w *TimeSelectW) Options() []Option {
	return moreTimeItems(w.start, w.end, w.step, w.minT, w.maxT)
}

func moreTimeItems(start, end, step, minT, maxT string) []Option {
	a, b, st := dtParseHM(start), dtParseHM(end), dtParseHM(step)
	if a < 0 || b < 0 || st <= 0 {
		return nil
	}
	lo, hi := dtParseHM(minT), dtParseHM(maxT)
	var out []Option
	for t := a; t <= b && len(out) < 24*60; t += st {
		s := dtFormatHM(t)
		dis := (minT != "" && lo >= 0 && t <= lo) || (maxT != "" && hi >= 0 && t >= hi)
		out = append(out, Option{Label: s, Value: s, Disabled: dis})
	}
	return out
}

func (w *TimeSelectW) isDisabled() bool { return w.disabled || w.n.disabled }

func (w *TimeSelectW) index(v string) int {
	for i, o := range w.items {
		if o.Value == v {
			return i
		}
	}
	return -1
}

func (w *TimeSelectW) step1(from, dir int) int {
	n := len(w.items)
	if n == 0 {
		return -1
	}
	i := from
	for k := 0; k < n; k++ {
		i += dir
		if i < 0 {
			i = n - 1
		} else if i >= n {
			i = 0
		}
		if !w.items[i].Disabled {
			return i
		}
	}
	return -1
}

func (w *TimeSelectW) openList() {
	w.st.open, w.st.scroll = true, true
	w.st.active = w.index(*w.val)
	w.c.invalid = true
}

func (w *TimeSelectW) pick(o Option) {
	if *w.val != o.Value {
		*w.val = o.Value
		w.changed = true
	}
	w.st.open = false
	w.c.SetFocus(w.n.id)
	w.c.invalid = true
}

func (w *TimeSelectW) height() float32 { return w.c.controlHeight(w.size) }

func (w *TimeSelectW) finish() {
	c, th := w.c, w.c.Theme
	st := w.st
	w.items = moreTimeItems(w.start, w.end, w.step, w.minT, w.maxT)
	w.n.ln.Height = w.height()
	if w.n.ln.Width == 0 {
		w.n.ln.Width = 160
		if th.Flavor == theme.Element {
			w.n.ln.Width = 240
		}
	}
	if st.open && st.active == -1 {
		st.active = w.index(*w.val)
	}
	if w.isDisabled() {
		st.open = false
		return
	}
	if w.ia.Clicked {
		if w.clearHit() {
			if *w.val != "" {
				*w.val = ""
				w.changed = true
			}
			st.open = false
		} else if st.open {
			st.open = false
		} else {
			w.openList()
		}
		c.invalid = true
	}
	if st.open && c.PressedOutside(w.n.id, st.panel) {
		st.open = false
		c.invalid = true
	}
	if st.open && c.focus != 0 && c.focus != w.n.id {
		st.open = false // focus moved on (Tab)
		c.invalid = true
	}
	if st.open && c.EscapeAt(st.panel) {
		st.open = false
		c.invalid = true
	}
	for _, k := range c.KeysFor(w.n.id) {
		if !k.Down {
			continue
		}
		switch k.Key {
		case input.KeyDown, input.KeyUp:
			dir := 1
			if k.Key == input.KeyUp {
				dir = -1
			}
			if !st.open {
				w.openList()
			} else if i := w.step1(st.active, dir); i >= 0 {
				st.active, st.follow = i, true
			}
		case input.KeyEnter, input.KeySpace:
			if !st.open {
				w.openList()
			} else if st.active >= 0 && st.active < len(w.items) && !w.items[st.active].Disabled {
				w.pick(w.items[st.active])
			}
		case input.KeyBackspace, input.KeyDelete:
			if w.clearable && *w.val != "" && !st.open {
				*w.val = ""
				w.changed = true
			}
		}
		c.invalid = true
	}
	if st.open {
		w.dropdown()
	}
	st.ptr = c.pointer
}

// clearHit reports a click on the clear icon area.
func (w *TimeSelectW) clearHit() bool {
	if !w.clearable || *w.val == "" {
		return false
	}
	r := w.c.rects[w.n.id]
	if w.c.IsRTL() { // clear at the inline end
		return w.c.pointer.X < r.X+30
	}
	return w.c.pointer.X > r.Right()-30
}

// optionH is the option row height (the Select token's OptionHeight).
func (w *TimeSelectW) optionH() float32 {
	return w.c.ThemeFor(theme.CompSelect).Components.Select.OptionHeight
}

func (w *TimeSelectW) dropdown() {
	c, th := w.c, w.c.Theme
	el := th.Flavor == theme.Element
	st := w.st
	a := c.AnimFrom(w.n.id, "open", 0, 1, th.DurationMid)
	oh := w.optionH()
	moved := c.pointer != st.ptr
	pad := float32(4)
	if el {
		pad = 6
	}
	maxH := float32(256)
	if el {
		maxH = 274 - 2*pad
	}
	ov := Overlay(c, OverlayOptions{Anchor: w.n.id, Place: BottomStart, Offset: 4, MatchWidth: true, Flip: true, ShiftY: (1 - a) * -4}, func() {
		if len(w.items) == 0 {
			Empty(c).Simple().Description(c.Locale().NoData)
			return
		}
		sb := Scroll(c, func() {
			w.optIDs = w.optIDs[:0]
			for i, o := range w.items {
				i, o := i, o
				it := c.add("option", o.Label)
				w.optIDs = append(w.optIDs, it.id)
				it.setRole(a11y.RoleOption).setState(a11y.Selectable).stateIf(o.Value == *w.val, a11y.Selected)
				it.ln.Height = oh
				ia := c.interact(it, false, input.CursorPointer)
				if o.Disabled {
					it.disabled, it.cursor = true, input.CursorNotAllowed
				}
				if ia.Hovered && moved && !o.Disabled && st.active != i {
					st.active = i
				}
				if ia.Clicked && !o.Disabled {
					w.pick(o)
				}
				it.paint = func(l *paint.List, r geom.Rect) { w.paintOption(l, r, o, i) }
			}
		}, layout.MaxH(maxH), layout.Padding(geom.VH(pad, morePick(el, 0, pad))))
		st.list = sb.n.id
		// The list is named like its combobox.
		sb.n.setRole(a11y.RoleListbox).setName(w.placeholder)
		if w.n.aNameSet {
			sb.n.setName(w.n.aName)
		}
		s := sb.s
		view := s.view.H
		if view <= 0 {
			view = maxH
		}
		if st.scroll {
			// On open, like Element, bring the current value near the top;
			// an empty value starts at the top.
			st.scroll = false
			s.off.Y = 0
			if i := w.index(*w.val); i >= 0 {
				s.off.Y = max(0, float64(i)*float64(oh))
			}
		}
		if st.follow {
			// Keyboard moves keep the highlight visible with minimal scrolling.
			st.follow = false
			if i := st.active; i >= 0 {
				top := float64(pad) + float64(i)*float64(oh)
				if top < s.off.Y {
					s.off.Y = top - float64(pad)
				} else if top+float64(oh) > s.off.Y+float64(view) {
					s.off.Y = top + float64(oh+pad-view)
				}
			}
		}
	})
	_, tk := dtTheme(c)
	if el {
		ov.Bg(tk.PanelBg).Radius(th.Radius).Border(1, th.BorderSecondary).Shadow(tk.PanelShadow)
	} else {
		ov.Bg(tk.PanelBg).Radius(tk.PanelRadius).Shadow(tk.PanelShadow)
		entPopupBorder(c, ov)
	}
	ov.n.clip = true
	ov.Opacity(a)
	st.panel = ov.n.id
}

func morePick(cond bool, a, b float32) float32 {
	if cond {
		return a
	}
	return b
}

// paintOption draws an option row like a Select option, from the Select
// token (option colors, weight, padding and font size).
func (w *TimeSelectW) paintOption(l *paint.List, r geom.Rect, o Option, i int) {
	c := w.c
	th := c.ThemeFor(theme.CompSelect)
	tk := &th.Components.Select
	el := th.Flavor == theme.Element
	sel := o.Value == *w.val
	act := w.st.active == i
	col, wt := th.Text, text.Regular
	if el {
		col = th.TextSecondary
	}
	rad := geom.Rad(th.RadiusSM)
	if el {
		rad = geom.Radii{}
	}
	switch {
	case o.Disabled:
		col = th.TextDisabled
	case sel && el:
		col, wt = tk.OptionSelectedColor, themeWeight(tk.OptionSelectedFontWeight)
		if act {
			l.Fill(r, rad, tk.OptionActiveBg)
		}
	case th.Flavor == theme.StyleShadcn:
		// shadcn SelectItem: accent on the highlighted row only, the
		// selected one carries a check at the right.
		if act {
			l.Fill(r, rad, tk.OptionActiveBg)
			col = th.ItemSelected
		}
		if sel { // check at the inline end
			is := float32(16)
			drawIcon(l, icon.Check, dtMirror(c.IsRTL(), r, r.Right()-8-is, is), r.Y+(r.H-is)/2, is, col)
		}
	case sel:
		l.Fill(r, rad, tk.OptionSelectedBg)
		col, wt = tk.OptionSelectedColor, themeWeight(tk.OptionSelectedFontWeight)
	case act:
		l.Fill(r, rad, tk.OptionActiveBg)
	}
	lay := text.Shape(o.Label, c.style(tk.OptionFontSize, wt), text.Options{NoWrap: true})
	l.Glyphs(geom.Pt(dtMirror(c.IsRTL(), r, r.X+tk.OptionPadding, lay.Width), r.Y+(r.H-lay.Height)/2), lay.Glyphs, col)
}

func (w *TimeSelectW) paint(l *paint.List, r geom.Rect) {
	c, th := w.c, w.c.Theme
	el := th.Flavor == theme.Element
	dis := w.isDisabled()
	shad := th.Flavor == theme.StyleShadcn
	rad := geom.Rad(c.controlRadius(w.size))
	if w.variant == "underlined" {
		rad = geom.Radii{}
	}
	focus := w.st.open || c.focus == w.n.id
	c.paintFrame(l, r, rad, w.n.id, frameState{hover: w.ia.Hovered, focus: focus, disabled: dis, status: w.status, variant: w.variant})
	fs := c.controlFont(w.size)
	st := c.style(fs, text.Regular)
	padX := float32(11)
	if w.size == Small {
		padX = 7
	}
	if shad {
		padX = th.ControlPaddingH
	}
	is := float32(14)
	x := r.X + padX
	// Laid out in LTR terms; mx / mr mirror into place in RTL (prefix
	// clock at the inline start, value, suffix icon at the inline end).
	rtl := c.IsRTL()
	mx := func(x, w float32) float32 { return dtMirror(rtl, r, x, w) }
	mr := func(rr geom.Rect) geom.Rect { return dtMirrorRect(rtl, rr, r) }
	icCol := th.TextQuaternary
	if el {
		icCol = th.TextTertiary
	}
	if el {
		// Element shows the clock as a prefix icon.
		drawIcon(l, icon.Clock, mx(x, is), r.Y+(r.H-is)/2, is, icCol)
		x += is + 8
	}
	s, col := *w.val, th.Text
	if dis {
		col = th.TextDisabled
	}
	if s == "" {
		s, col = w.placeholder, th.TextQuaternary
		if el {
			col = th.TextTertiary
		}
	}
	right := r.Right() - padX - is - 4
	lay := text.Shape(s, st, text.Options{NoWrap: true, Ellipsis: true, MaxWidth: max(0, right-x)})
	l.Glyphs(geom.Pt(mx(x, lay.Width), r.Y+(r.H-lay.Height)/2), lay.Glyphs, col)
	ir := mr(geom.Rect{X: r.Right() - padX - is, Y: r.Y + (r.H-is)/2, W: is, H: is})
	if w.clearable && *w.val != "" && w.ia.Hovered && !dis {
		if shad {
			entClearIcon(c, l, ir)
			return
		}
		drawStatusIcon(l, "error", ir.Inset(geom.All(1)), th.TextQuaternary, th.BgContainer)
		return
	}
	if shad {
		// shadcn SelectTrigger: chevron-down at 50% opacity.
		is := float32(16)
		drawIcon(l, icon.Down, mx(r.Right()-padX-is, is), r.Y+(r.H-is)/2, is, theme.Fade(th.Text, .5))
		return
	}
	if el {
		ang := float64(c.Anim(w.n.id, "arrow", b2f(w.st.open), th.DurationMid)) * 3.14159
		icon.Draw(l, icon.Down, ir.Inset(geom.All(1)), icCol, ang)
		return
	}
	drawIcon(l, icon.Clock, ir.X, ir.Y, is, icCol)
}
